"""Primary metadata/abstract decisions for the three 2020 bibliography entries."""
import json
import ledger as L
from review_batch_0001 import evidence

def main():
 rid='author-castro-osu';before=L.counts();inv=json.loads((L.HERE/'castro_bibliography_inventory.json').read_text());pubs={p['registry_key']:p for p in L.read('publication_reviews')};edges={e['edge_id']:e for e in L.read('discovery_edges')}
 cases=[(151,'10.1039/c9nh00529c','Dynamic DNA nanotechnology: toward functional nanoscale devices','2019-10-15','background_or_review','review','castro_boundary_search.json','https://pubs.rsc.org/en/content/articlelanding/2020/nh/c9nh00529c','Publisher labels Review Article and explicitly gives first published15Oct2019 despite2020 issue. Abstract describes review of dynamic-device design, behavior characterization/prediction and challenges. In-date literature/citation seed; no new design inferred from the review abstract.'),(149,'10.1039/d0nr00952k','An electrochemical biosensor exploiting binding-induced changes in electron transfer of electrode-attached DNA origami to detect hundred nanometer-scale targets','2020-06-18','design_bearing','journal_article','castro_boundary_dates.json','https://pubs.rsc.org/en/content/articlelanding/2020/nr/d0nr00952k','Publisher abstract reports triangular origami attached to gold electrodes with redox reporters and target recognition sites separated by about40nm. First published18Jun2020: this journal version is outside cutoff; earlier public version and exact design/source identity remain unverified.'),(150,'10.1088/1758-5090/ab97a1','Direct-write 3D printing and characterization of a GelMA-based biomaterial for intracorporeal tissue','2020-07-21','uncertain','journal_article','castro_boundary_dates.json','https://pubmed.ncbi.nlm.nih.gov/32464607/','PubMed author/title/DOI matches OSU citation, with displayed21Jul2020 date. Abstract concerns GelMA/Laponite/methylcellulose tissue-scaffold printing, not a DNA design; retain provisional scope pending main text. Secondary search reports28May2020; earliest publisher date not verified. IOP browser access blocked by robots.')]
 keys=[]
 for line,key,title,date,rel,typ,file,url,note in cases:
  ev=evidence(L.HERE/file,url,'Primary metadata and abstract in saved search result; not direct fulltext acquisition');keys.append(key)
  if key not in pubs:
   p=dict(registry_key=key,registry_id=None,doi=key,title=title,canonical_work_id='work:'+key,canonical_work_status='provisional_unreconciled',version_links=[],publication_type=[typ],date_evidence={'date':date,'source':ev,'primary_verified':True,'meaning':'First published publisher date' if line!=150 else 'PubMed displayed date; earliest online unresolved'},review_stage='metadata_screened',relevance=rel,design_contributions=['uncertain'],catalog_eligibility='unresolved',access='partial',evidence=[ev],rationale=note,reviewer='Codex primary metadata/abstract inspection',run_id=rid,date=L.DATE,unresolved_questions=['Reconcile earlier versions and full author list; inspect main text and design/source scope.','Follow primary references where relevant; do not infer complete designs from abstract.'],legacy_record={})
   p['temporal_scope']='pre2020_verified' if line==151 else ('journal_version_post_cutoff_verified; earlier_versions_pending' if line==149 else '2020_date_observed; earliest_online_pending')
   L.upsert('publication_reviews',p,'Retain boundary version with explicit evidence depth')
  entry=next(e for e in inv['entries'] if e['source_line']==line);entry.update(identity_status='primary_bibliographic_match',target_key=key,review_note=note)
  edge=edges[rid+':'+entry['lead_key']];edge.update(target_key=key,reconciliation_state='matched_primary_identity; version_source_scope_pending',identity_evidence=ev,reconciliation_note=note);L.upsert('discovery_edges',edge,'Resolve boundary bibliography identity without merging versions')
 L.atomic(L.HERE/'castro_bibliography_inventory.json',json.dumps(inv,indent=2)+'\n')
 run=next(r for r in L.read('discovery_runs') if r['run_id']==rid);run.update(checkpoint='Three of45 entries identity-matched. Review C9NH00529C first published2019-10-15 despite2020 issue; D0NR00952K first published2020-06-18; GelMA earliest-online date unresolved.42 bibliography identities remain. Review main text/citations and compare CV while rotating requested authors.',identity_matched_entries=3,identity_pending_entries=42)
 L.upsert('discovery_runs',run,'Record three boundary checks and remaining queue')
 b=dict(batch_id='AUTHOR0001',date=L.DATE,status='completed',input_keys=keys,selection='All three2020 boundary entries in Castro official bibliography',completed_actions=['Primary bibliographic matching and abstract inspection for3 entries; dates kept separate from issue years.'],before_counts=before,after_counts=L.counts(),unresolved_keys=keys,exclusion_audit={'sample':[],'reason':'No final catalog exclusions; scope/version questions explicit.'},validation=[L.validate()],next_queue=['Acquire C9NH00529C fulltext and traverse references','Resolve remaining42 Castro bibliography entries and CV completeness','Rotate other requested author histories; FNANO deferred'])
 L.upsert('batches',b,'Save boundary-review batch retaining all follow-ups');print(L.validate())
if __name__=='__main__':main()
